using NUnit.Framework;

[TestFixture]
public class TwoSumTests
{
    [Test]
    public void Returns_Indices_For_First_Example()
    {
        var result = TwoSum(new[] { 2, 7, 11, 15 }, 9);
        Assert.That(result, Is.EqualTo(new[] { 0, 1 }));
    }

    [Test]
    public void Returns_Indices_For_Second_Example()
    {
        var result = TwoSum(new[] { 3, 2, 4 }, 6);
        Assert.That(result, Is.EqualTo(new[] { 1, 2 }));
    }

    [Test]
    public void Returns_Indices_For_Duplicate_Values()
    {
        var result = TwoSum(new[] { 3, 3 }, 6);
        Assert.That(result, Is.EqualTo(new[] { 0, 1 }));
    }

    private int[] TwoSum(int[] nums, int target)
    {
        var seen = new Dictionary<int, int>();

        for (int i = 0; i < nums.Length; i++)
        {
            int complement = target - nums[i];

            if (seen.ContainsKey(complement))
                return new[] { seen[complement], i };

            seen[nums[i]] = i;
        }

        throw new ArgumentException("No solution found");
    }
}
